effect.shader:
// Uma caixa do AM no alfa de `fonte`: o centro e n amostras de cada lado até ±alcance, com o filtro linear. As contas
// são escritas como as do AM (o ângulo em graus × 0,0174533, a velocidade ÷ o texel) para dar o mesmo n.
float caixa(sampler2D fonte, float graus, float alcance) {
    vec2 texel = 1.0 / vec2(textureSize(fonte, 0));
    float rad = graus * 0.0174533;
    vec2 velocidade = vec2(cos(rad) * alcance, -sin(rad) * alcance);
    int n = int(clamp(length(velocidade / texel), 2.01, 100.01));
    float soma = texture(fonte, acScreenNorm).a;
    for (int i = 1; i < n; i++) {
        vec2 d = velocidade * (float(i) / float(n - 1));
        soma += texture(fonte, acScreenNorm + d).a;
        soma += texture(fonte, acScreenNorm - d).a;
    }
    return soma / float(n * 2 - 1);
}

void main() {
    vec4 camada = texture(inputImg, acScreenNorm);
    if (strength <= 0.005) {
        fragColor = camada;
        return;
    }
    float alcance = strength / 4.0 / iter;
    // Um ramo por passe, cada um terminando em `return`: é o formato que a poda do motor (`PodaDoPasse`)
    // corta por passe — um `else if` encadeado deixaria `else` solto no programa do último.
    if (acPass == 0) {
        fragColor = vec4(camada.a);                         // a metade: só o alfa interessa daqui em diante
        return;
    }
    if (acPass == 1) {
        fragColor = vec4(texture(ds1, acScreenNorm).a);     // a quarta parte
        return;
    }
    if (acPass == 2) {
        fragColor = vec4(caixa(ds2, 0.0, alcance));         // a caixa na horizontal
        return;
    }
    float a = caixa(hblur, 90.0, alcance);                  // na vertical, já subindo para a resolução cheia
    fragColor = vec4(camada.rgb, camada.a * a * a);         // reta: a cor fica, o alfa afina
}
